//// Supervised local control actor; transport is a separate worker. Clock reads
//// call standard ERTS directly. Actor lifetime IDs fence delayed delivery reports.
import cepaf_gleam/crdt/mesh_peer as peer
import cepaf_gleam/crdt/mesh_wire as wire
import cepaf_gleam/ha/deadman_freshness
import exception
import gleam/erlang/process.{type Subject}
import gleam/int
import gleam/list
import gleam/otp/actor
import gleam/otp/supervision
import gleam/result
import gleam/string

type TimeUnit { Millisecond Microsecond }
type UniqueOption { Positive Monotonic }
@external(erlang, "erlang", "monotonic_time")
fn monotonic_time(unit: TimeUnit) -> Int
@external(erlang, "erlang", "system_time")
fn system_time(unit: TimeUnit) -> Int
@external(erlang, "erlang", "unique_integer")
fn unique_integer(options: List(UniqueOption)) -> Int

pub opaque type Handle { Handle(subject: Subject(Message)) }
pub type View { View(peer: peer.State, last_tick_gossip: Result(Nil, peer.PeerError)) }
type Message {
  TimerTick
  Gossip(Subject(Result(Nil, peer.PeerError)))
  Inbound(String, String, Subject(Result(Nil, peer.PeerError)))
  Worker(String, Subject(Result(Nil, peer.PeerError)))
  Health(Float, Float, Bool, String, Subject(Result(Nil, peer.PeerError)))
  Pull(Int, Subject(Result(List(peer.Frame), peer.PeerError)))
  Report(peer.FrameId, String, peer.Delivery, Subject(Result(Nil, peer.PeerError)))
  Snapshot(Subject(Result(View, peer.PeerError)))
  Advisories(Subject(Result(#(List(deadman_freshness.DeadManAction), Int), peer.PeerError)))
  Shutdown(Subject(Result(View, peer.PeerError)))
}
type State {
  State(peer: peer.State, config: peer.Config, origin_mono: Int, subject: Subject(Message), timer: process.Timer, last_tick_gossip: Result(Nil, peer.PeerError))
}
fn mono(state: State) { int.max(0, monotonic_time(Millisecond) - state.origin_mono) }
fn view(state: State) { View(state.peer, state.last_tick_gossip) }
fn update(state: State, operation: Result(peer.State, peer.PeerError), reply: Subject(Result(Nil, peer.PeerError))) {
  case operation {
    Ok(next) -> { process.send(reply, Ok(Nil)) actor.continue(State(..state, peer: next)) }
    Error(error) -> { process.send(reply, Error(error)) actor.continue(state) }
  }
}
fn handle(state: State, message: Message) -> actor.Next(State, Message) {
  case message {
    TimerTick -> {
      let timer = process.send_after(state.subject, peer.tick_interval(state.config), TimerTick)
      actor.continue(State(..state, timer: timer))
    }
    Gossip(reply) -> update(state, peer.gossip(state.peer, system_time(Microsecond)), reply)
    Inbound(sender, bytes, reply) -> update(state, peer.receive_wire(state.peer, sender, bytes, mono(state), system_time(Microsecond)), reply)
    Worker(worker, reply) -> update(state, peer.record_worker(state.peer, worker, system_time(Microsecond)), reply)
    Health(score, exponent, stable, breaker, reply) -> update(state, peer.record_health(state.peer, score, exponent, stable, breaker, system_time(Microsecond)), reply)
    Pull(maximum, reply) -> {
      process.send(reply, Ok(list.take(peer.outbound(state.peer), maximum)))
      actor.continue(state)
    }
    Report(id, destination, outcome, reply) -> update(state, peer.report_delivery(state.peer, id, destination, outcome), reply)
    Snapshot(reply) -> { process.send(reply, Ok(view(state))) actor.continue(state) }
    Advisories(reply) -> {
      let #(next, actions, overflow) = peer.take_advisories(state.peer)
      process.send(reply, Ok(#(actions, overflow)))
      actor.continue(State(..state, peer: next))
    }
    Shutdown(reply) -> {
      let _ = process.cancel_timer(state.timer)
      process.send(reply, Ok(view(state)))
      actor.stop()
    }
  }
}
pub fn start(config: peer.Config) -> actor.StartResult(Handle) {
  actor.new_with_initialiser(1000, fn(subject) {
    let origin = monotonic_time(Millisecond)
    use initial <- result.try(peer.init(config, 0, system_time(Microsecond), unique_integer([Positive, Monotonic])) |> result.map_error(fn(_) { "invalid initial peer clocks" }))
    let timer = process.send_after(subject, peer.tick_interval(config), TimerTick)
    Ok(actor.initialised(State(initial, config, origin, subject, timer, Ok(Nil))) |> actor.returning(Handle(subject)))
  }) |> actor.on_message(handle) |> actor.start
}
/// Normal controlled shutdown is transient; abnormal crashes are supervised.
/// In-memory outbox durability across a VM/process crash is not claimed.
pub fn supervised(config: peer.Config) -> supervision.ChildSpecification(Handle) {
  supervision.worker(fn() { start(config) }) |> supervision.restart(supervision.Transient) |> supervision.timeout(1000)
}
fn call(handle: Handle, request: fn(Subject(Result(a, peer.PeerError))) -> Message) -> Result(a, peer.PeerError) {
  exception.rescue(fn() { process.call(handle.subject, 1000, request) })
  |> result.map_error(fn(_) { peer.ActorUnavailable }) |> result.flatten
}
pub fn gossip(handle: Handle) -> Result(Nil, peer.PeerError) { call(handle, Gossip) }
pub fn receive_wire(handle: Handle, routing_id: String, bytes: String) -> Result(Nil, peer.PeerError) {
  case string.byte_size(bytes) <= wire.max_bytes && string.byte_size(routing_id) <= wire.max_string_bytes {
    True -> call(handle, Inbound(routing_id, bytes, _))
    False -> Error(peer.WireFailure(wire.ByteLimit))
  }
}
pub fn record_worker(handle: Handle, worker: String) -> Result(Nil, peer.PeerError) {
  case string.byte_size(worker) <= wire.max_string_bytes {
    True -> call(handle, Worker(worker, _))
    False -> Error(peer.WireFailure(wire.StringLimit))
  }
}
pub fn record_health(handle: Handle, score: Float, exponent: Float, stable: Bool, breaker: String) -> Result(Nil, peer.PeerError) {
  use _ <- result.try(wire.validate(wire.Array([wire.Real(score), wire.Real(exponent), wire.Text(breaker)])) |> result.map_error(peer.WireFailure))
  call(handle, Health(score, exponent, stable, breaker, _))
}
/// Pulling transfers no custody: frames remain until their exact report arrives.
pub fn pull(handle: Handle, maximum: Int) -> Result(List(peer.Frame), peer.PeerError) {
  case maximum >= 1 && maximum <= peer.max_frames { True -> call(handle, Pull(maximum, _)) False -> Error(peer.InvalidConfig) }
}
pub fn report_delivery(handle: Handle, id: peer.FrameId, destination: String, outcome: peer.Delivery) -> Result(Nil, peer.PeerError) {
  case string.byte_size(destination) <= wire.max_string_bytes && id.instance >= 0 && id.instance <= wire.max_integer && id.sequence >= 0 && id.sequence <= wire.max_integer {
    True -> call(handle, Report(id, destination, outcome, _))
    False -> Error(peer.NotOutstanding)
  }
}
pub fn snapshot(handle: Handle) -> Result(View, peer.PeerError) { call(handle, Snapshot) }
pub fn take_advisories(handle: Handle) -> Result(#(List(deadman_freshness.DeadManAction), Int), peer.PeerError) { call(handle, Advisories) }
/// Caller receives the complete retained state for explicit shutdown handoff.
/// A failed/timed-out call does not establish that the handoff was received.
pub fn shutdown(handle: Handle) -> Result(View, peer.PeerError) { call(handle, Shutdown) }

import cepaf_gleam/crdt/mesh_peer.{Peer, TransportAccepted, FrameQuota}
import cepaf_gleam/crdt/mesh_peer_actor as peer_actor
import cepaf_gleam/crdt/mesh_sync
import cepaf_gleam/ha/deadman_freshness.{HeartbeatTripped, HeartbeatNominal}
import gleam/erlang/process
import gleam/io
import gleam/list
import gleam/otp/actor
import gleam/otp/static_supervisor
import gleam/otp/supervision
import gleeunit/should

fn config(node, other, tick, heartbeat) {
  let assert Ok(c) = mesh_peer.config(node, "http://nas-1.tail55d152.ts.net", [Peer(other, "http://vm-1.tail55d152.ts.net")], tick, heartbeat, 2)
  c
}
fn transfer(from, sender, target) {
  let assert Ok(frames) = peer_actor.pull(from, 256)
  list.each(frames, fn(frame) {
    peer_actor.receive_wire(target, sender, frame.wire) |> should.equal(Ok(Nil))
    peer_actor.report_delivery(from, frame.id, frame.destination, TransportAccepted) |> should.equal(Ok(Nil))
  })
}
pub fn two_actor_exchange_test() {
  let assert Ok(a) = peer_actor.start(config("a", "b", 1000, 2000))
  let assert Ok(b) = peer_actor.start(config("b", "a", 1000, 2000))
  peer_actor.record_worker(a.data, "worker") |> should.equal(Ok(Nil))
  peer_actor.gossip(a.data) |> should.equal(Ok(Nil))
  peer_actor.gossip(b.data) |> should.equal(Ok(Nil))
  transfer(a.data, "a", b.data)
  transfer(b.data, "b", a.data)
  transfer(a.data, "a", b.data)
  transfer(b.data, "b", a.data)
  let assert Ok(view) = peer_actor.snapshot(b.data)
  mesh_peer.engine_snapshot(view.peer).local_mesh_state.active_workers.elements
  |> list.any(fn(p) { p.0 == "worker" }) |> should.be_true
  let assert Ok(_) = peer_actor.shutdown(a.data)
  let assert Ok(_) = peer_actor.shutdown(b.data)
}
fn fill(handle, left) {
  case left { 0 -> panic as "queue failed to fill" _ -> case peer_actor.gossip(handle) {
    Ok(Nil) -> fill(handle, left - 1)
    Error(FrameQuota) -> Nil
    Error(_) -> panic as "unexpected queue refusal"
  } }
}
pub fn timer_full_queue_and_replay_test() {
  let assert Ok(started) = peer_actor.start(config("a", "b", 10, 20))
  let handle = started.data
  let assert Ok(bytes) = mesh_sync.encode_sync_message(mesh_sync.SyncAck("b", [], "ok", 1))
  peer_actor.receive_wire(handle, "b", bytes) |> should.equal(Ok(Nil))
  fill(handle, 300)
  process.sleep(100)
  let assert Ok(view) = peer_actor.snapshot(handle)
  list.length(mesh_peer.outbound(view.peer)) |> should.equal(256)
  let assert [entry] = mesh_peer.freshness(view.peer).actors
  case entry.status { HeartbeatTripped(_) -> Nil _ -> panic as "timer did not trip full queue" }
  peer_actor.receive_wire(handle, "b", bytes) |> should.equal(Ok(Nil))
  let assert Ok(replayed) = peer_actor.snapshot(handle)
  let assert [after] = mesh_peer.freshness(replayed.peer).actors
  after.status |> should.equal(entry.status)
  let assert Ok(shutdown) = peer_actor.shutdown(handle)
  list.length(mesh_peer.outbound(shutdown.peer)) |> should.equal(256)
  process.sleep(5)
  peer_actor.snapshot(handle) |> should.equal(Error(mesh_peer.ActorUnavailable))
}
pub fn supervised_child_shutdown_test() {
  let replies = process.new_subject()
  let specification = peer_actor.supervised(config("a", "b", 1000, 2000))
  let child = supervision.ChildSpecification(..specification, start: fn() {
    case specification.start() {
      Ok(started) -> { process.send(replies, started.data) Ok(started) }
      Error(e) -> Error(e)
    }
  })
  let assert Ok(supervised) = static_supervisor.new(static_supervisor.OneForOne) |> static_supervisor.add(child) |> static_supervisor.start
  let assert Ok(handle) = process.receive(replies, 1000)
  let assert Ok(view) = peer_actor.snapshot(handle)
  let assert [entry] = mesh_peer.freshness(view.peer).actors
  entry.status |> should.equal(HeartbeatNominal)
  let assert Ok(_) = peer_actor.shutdown(handle)
  process.receive(replies, 30) |> should.equal(Error(Nil))
  process.unlink(supervised.pid)
  process.send_exit(supervised.pid)
}
pub fn main() {
  two_actor_exchange_test()
  io.println("PASS two_actor_exchange")
  supervised_child_shutdown_test()
  io.println("PASS supervised_child_shutdown")
  timer_full_queue_and_replay_test()
  io.println("PASS timer_full_queue_and_replay")
}

//// Opaque cooperative peer state. Routing checks are not authentication.
//// Outbound acceptance means transport custody, not remote application.
import cepaf_gleam/crdt/delta_mesh_engine as engine
import cepaf_gleam/crdt/mesh_sync as sync
import cepaf_gleam/crdt/mesh_wire as wire
import cepaf_gleam/ha/deadman_freshness as deadman
import gleam/int
import gleam/list
import gleam/option.{None}
import gleam/result
import gleam/string

pub const max_peers = 16
pub const max_frames = 256
pub const max_outbound_bytes = 1_048_576
pub const max_advisories = 64

pub type Peer { Peer(node: String, fqdn: String) }
pub opaque type Config {
  Config(node: String, fqdn: String, peers: List(Peer), tick_ms: Int, heartbeat_ms: Int, max_missed: Int)
}
pub type PeerError {
  InvalidConfig
  InvalidClock
  UnknownPeer
  SenderMismatch
  WireFailure(wire.WireError)
  EngineQueueFull
  FrameQuota
  ByteQuota
  SequenceLimit
  NotOutstanding
  ActorUnavailable
}
pub type FrameId { FrameId(instance: Int, sequence: Int) }
pub type Frame { Frame(id: FrameId, destination: String, wire: String) }
pub type Delivery { TransportAccepted TransportFailed }
pub opaque type State {
  State(config: Config, engine: engine.DeltaMeshEngine, freshness: deadman.DeadManRegistry,
    activity: List(#(String, Int)), outbox: List(Frame), bytes: Int, next_id: Int,
    instance: Int, last_mono: Int, actions: List(deadman.DeadManAction), action_overflow: Int)
}
pub type Tick { Tick(state: State, gossip: Result(Nil, PeerError)) }

fn bounded(items: List(a), count: Int) -> Bool {
  case items { [] -> True [_, ..rest] -> count > 0 && bounded(rest, count - 1) }
}
fn identity(value: String) -> Bool {
  string.trim(value) != "" && string.byte_size(value) <= wire.max_string_bytes
}
pub fn config(node: String, fqdn: String, peers: List(Peer), tick_ms: Int, heartbeat_ms: Int, max_missed: Int) -> Result(Config, PeerError) {
  case identity(node) && identity(fqdn) && bounded(peers, max_peers)
    && list.all(peers, fn(p) { identity(p.node) && identity(p.fqdn) && p.node != node })
    && list.length(list.unique(list.map(peers, fn(p) { p.node }))) == list.length(peers)
    && tick_ms >= 1 && tick_ms <= 60_000 && heartbeat_ms >= tick_ms
    && heartbeat_ms <= 60_000 && max_missed >= 1 && max_missed <= 100 {
    True -> Ok(Config(node, fqdn, peers, tick_ms, heartbeat_ms, max_missed))
    False -> Error(InvalidConfig)
  }
}
pub fn tick_interval(config: Config) -> Int { config.tick_ms }
fn valid_clock(value: Int) -> Bool { value >= 0 && value <= wire.max_integer }
pub fn init(config: Config, mono_ms: Int, utc_us: Int, instance: Int) -> Result(State, PeerError) {
  case valid_clock(mono_ms) && valid_clock(utc_us) && valid_clock(instance) {
    False -> Error(InvalidClock)
    True -> {
      let initial = engine.init_engine(config.node, config.fqdn, utc_us)
      let registered = list.fold(config.peers, initial, fn(e, p) { engine.register_peer(e, p.node, p.fqdn) })
      let freshness = list.fold(config.peers, deadman.init_deadman_registry(), fn(r, p) {
        deadman.register_actor(r, p.node, "L6", config.heartbeat_ms, config.max_missed, None, mono_ms)
      })
      Ok(State(config, registered, freshness, [], [], 0, 1, instance, mono_ms, [], 0))
    }
  }
}
pub fn outbound(state: State) -> List(Frame) { state.outbox }
pub fn outbound_bytes(state: State) -> Int { state.bytes }
pub fn engine_snapshot(state: State) -> engine.DeltaMeshEngine { state.engine }
pub fn freshness(state: State) -> deadman.DeadManRegistry { state.freshness }
pub fn advisory_overflow(state: State) -> Int { state.action_overflow }
pub fn take_advisories(state: State) -> #(State, List(deadman.DeadManAction), Int) {
  #(State(..state, actions: [], action_overflow: 0), state.actions, state.action_overflow)
}
fn check_engine(candidate: engine.DeltaMeshEngine) -> Result(Nil, PeerError) {
  sync.encode_sync_message(sync.SyncDelta(candidate.local_node_id, candidate.local_mesh_state, candidate.local_health_map, candidate.local_mesh_state.epoch_us))
  |> result.map(fn(_) { Nil }) |> result.map_error(WireFailure)
}
fn add_frame(state: State, destination: String, bytes: String) -> Result(State, PeerError) {
  case list.length(state.outbox) >= max_frames, state.bytes + string.byte_size(bytes) > max_outbound_bytes, state.next_id >= wire.max_integer {
    True, _, _ -> Error(FrameQuota)
    _, True, _ -> Error(ByteQuota)
    _, _, True -> Error(SequenceLimit)
    False, False, False -> Ok(State(..state,
      outbox: list.append(state.outbox, [Frame(FrameId(state.instance, state.next_id), destination, bytes)]),
      bytes: state.bytes + string.byte_size(bytes), next_id: state.next_id + 1))
  }
}
fn route_messages(state: State, messages: List(sync.MeshSyncMessage), destinations: List(String)) -> Result(State, PeerError) {
  list.try_fold(messages, state, fn(s, message) {
    use bytes <- result.try(sync.encode_sync_message(message) |> result.map_error(WireFailure))
    list.try_fold(destinations, s, fn(s, destination) { add_frame(s, destination, bytes) })
  })
}
fn commit_engine(state: State, candidate: engine.DeltaMeshEngine, destinations: List(String)) -> Result(State, PeerError) {
  use _ <- result.try(check_engine(candidate))
  let #(drained, messages) = engine.drain_pending_outbound(candidate)
  use staged <- result.try(route_messages(state, messages, destinations))
  Ok(State(..staged, engine: drained))
}
pub fn gossip(state: State, utc_us: Int) -> Result(State, PeerError) {
  use _ <- result.try(case valid_clock(utc_us) { True -> Ok(Nil) False -> Error(InvalidClock) })
  use #(candidate, _) <- result.try(engine.generate_gossip_digest(state.engine, utc_us) |> result.map_error(fn(_) { EngineQueueFull }))
  commit_engine(state, candidate, list.map(state.config.peers, fn(p) { p.node }))
}
pub fn record_worker(state: State, worker: String, utc_us: Int) -> Result(State, PeerError) {
  use _ <- result.try(case valid_clock(utc_us) { True -> Ok(Nil) False -> Error(InvalidClock) })
  commit_engine(state, engine.record_worker_active(state.engine, worker, utc_us), [])
}
pub fn record_health(state: State, score: Float, exponent: Float, stable: Bool, breaker: String, utc_us: Int) -> Result(State, PeerError) {
  use _ <- result.try(case valid_clock(utc_us) { True -> Ok(Nil) False -> Error(InvalidClock) })
  commit_engine(state, engine.record_local_health(state.engine, state.config.node, score, exponent, stable, breaker, utc_us), [])
}
pub fn receive_wire(state: State, routing_id: String, bytes: String, mono_ms: Int, utc_us: Int) -> Result(State, PeerError) {
  use _ <- result.try(case valid_clock(mono_ms) && mono_ms >= state.last_mono && valid_clock(utc_us) { True -> Ok(Nil) False -> Error(InvalidClock) })
  use _ <- result.try(case list.any(state.config.peers, fn(p) { p.node == routing_id }) { True -> Ok(Nil) False -> Error(UnknownPeer) })
  use message <- result.try(sync.decode_sync_message(bytes) |> result.map_error(WireFailure))
  let #(sender, remote_epoch) = case message {
    sync.SyncDigest(node, _, _, epoch) | sync.SyncDelta(node, _, _, epoch) | sync.SyncAck(node, _, _, epoch) -> #(node, epoch)
  }
  use _ <- result.try(case sender == routing_id { True -> Ok(Nil) False -> Error(SenderMismatch) })
  use #(candidate, _) <- result.try(engine.handle_incoming_message(state.engine, message, utc_us) |> result.map_error(fn(_) { EngineQueueFull }))
  use accepted <- result.try(commit_engine(state, candidate, [sender]))
  let previous = list.key_find(state.activity, sender) |> result.unwrap(-1)
  case remote_epoch > previous {
    True -> Ok(State(..accepted,
      activity: list.key_set(state.activity, sender, remote_epoch),
      freshness: deadman.record_heartbeat(state.freshness, sender, mono_ms), last_mono: mono_ms))
    False -> Ok(State(..accepted, last_mono: mono_ms))
  }
}
/// Only the exact retained frame/address pair can retire. Failed transport
/// preserves all bytes and IDs, permitting a later retry of that same frame.
pub fn report_delivery(state: State, id: FrameId, destination: String, outcome: Delivery) -> Result(State, PeerError) {
  use frame <- result.try(list.find(state.outbox, fn(f) { f.id == id && f.destination == destination }) |> result.map_error(fn(_) { NotOutstanding }))
  case outcome {
    TransportFailed -> Ok(state)
    TransportAccepted -> Ok(State(..state, outbox: list.filter(state.outbox, fn(f) { f.id != id }), bytes: state.bytes - string.byte_size(frame.wire)))
  }
}
/// Freshness commits independently of gossip quota. Advisory overflow is counted
/// explicitly; authoritative current statuses remain in the bounded registry.
pub fn tick(state: State, mono_ms: Int, utc_us: Int) -> Result(Tick, PeerError) {
  use _ <- result.try(case valid_clock(mono_ms) && mono_ms >= state.last_mono && valid_clock(utc_us) { True -> Ok(Nil) False -> Error(InvalidClock) })
  let #(registry, actions) = deadman.evaluate_freshness_tick(state.freshness, mono_ms)
  let all = list.append(state.actions, actions)
  let fresh = State(..state, freshness: registry, last_mono: mono_ms,
    actions: list.take(all, max_advisories), action_overflow: int.min(wire.max_integer, state.action_overflow + int.max(0, list.length(all) - max_advisories)))
  case gossip(fresh, utc_us) {
    Ok(sent) -> Ok(Tick(sent, Ok(Nil)))
    Error(error) -> Ok(Tick(fresh, Error(error)))
  }
}

import cepaf_gleam/crdt/mesh_peer.{Peer, FrameId, TransportFailed, TransportAccepted, FrameQuota, ByteQuota, UnknownPeer, SenderMismatch, InvalidClock, NotOutstanding, Tick}
import cepaf_gleam/crdt/mesh_sync.{SyncAck, SyncDigest, SyncDelta}
import cepaf_gleam/crdt/delta_state
import cepaf_gleam/ha/deadman_freshness.{HeartbeatTripped}
import gleam/int
import gleam/io
import gleam/list
import gleam/result
import gleam/string
import gleeunit/should

pub fn valid_configuration_test() {
  mesh_peer.config("a", "http://nas-1.tail55d152.ts.net", [Peer("b", "http://vm-1.tail55d152.ts.net")], 10, 50, 3)
  |> result.is_ok |> should.be_true
}

fn configured(peers) {
  let assert Ok(config) = mesh_peer.config("a", "http://nas-1.tail55d152.ts.net", peers, 10, 50, 2)
  let assert Ok(state) = mesh_peer.init(config, 0, 1000, 1)
  state
}
fn initial() { configured([Peer("b", "http://vm-1.tail55d152.ts.net")]) }
fn encode(message) { let assert Ok(bytes) = mesh_sync.encode_sync_message(message) bytes }
fn gossip_n(state, n) {
  case n { 0 -> state _ -> { let assert Ok(next) = mesh_peer.gossip(state, 1000 + n) gossip_n(next, n - 1) } }
}

pub fn configuration_bounds_test() {
  mesh_peer.config("a", "fqdn", [Peer("a", "other")], 1, 50, 2) |> result.is_error |> should.be_true
  mesh_peer.config("a", "fqdn", list.repeat(Peer("b", "other"), 2), 1, 50, 2) |> result.is_error |> should.be_true
  mesh_peer.config("a", "fqdn", [], 0, 50, 2) |> result.is_error |> should.be_true
  let peers = list.index_map(list.repeat(Nil, 17), fn(_, i) { Peer(int.to_string(i), "fqdn") })
  mesh_peer.config("a", "fqdn", peers, 1, 50, 2) |> result.is_error |> should.be_true
}
pub fn routes_and_delivery_test() {
  let state = configured([Peer("b", "b.fqdn"), Peer("c", "c.fqdn")])
  let assert Ok(queued) = mesh_peer.gossip(state, 1001)
  let assert [first, second] = mesh_peer.outbound(queued)
  first.destination |> should.equal("b")
  second.destination |> should.equal("c")
  mesh_peer.report_delivery(queued, first.id, "c", TransportAccepted) |> should.equal(Error(NotOutstanding))
  mesh_peer.report_delivery(queued, first.id, "b", TransportFailed) |> should.equal(Ok(queued))
  let assert Ok(retired) = mesh_peer.report_delivery(queued, first.id, "b", TransportAccepted)
  mesh_peer.outbound(retired) |> should.equal([second])
  mesh_peer.report_delivery(retired, first.id, "b", TransportAccepted) |> should.equal(Error(NotOutstanding))
  mesh_peer.report_delivery(retired, FrameId(99, 1), "c", TransportAccepted) |> should.equal(Error(NotOutstanding))
}
pub fn incoming_routing_test() {
  let state = initial()
  let bytes = encode(SyncDigest("b", [], 0, 1))
  mesh_peer.receive_wire(state, "x", bytes, 1, 1001) |> should.equal(Error(UnknownPeer))
  mesh_peer.receive_wire(state, "b", encode(SyncAck("c", [], "ok", 1)), 1, 1001) |> should.equal(Error(SenderMismatch))
  mesh_peer.receive_wire(state, "b", "[]", 1, 1001) |> result.is_error |> should.be_true
  let assert Ok(next) = mesh_peer.receive_wire(state, "b", bytes, 1, 1001)
  list.map(mesh_peer.outbound(next), fn(f) { f.destination }) |> should.equal(["b"])
}
pub fn replay_does_not_rearm_test() {
  let state = initial()
  let bytes = encode(SyncAck("b", [], "ok", 1))
  let assert Ok(observed) = mesh_peer.receive_wire(state, "b", bytes, 1, 1001)
  let assert Ok(Tick(tripped, _)) = mesh_peer.tick(observed, 101, 1101)
  let assert [entry] = mesh_peer.freshness(tripped).actors
  entry.status |> should.equal(HeartbeatTripped(101))
  let assert Ok(replayed) = mesh_peer.receive_wire(tripped, "b", bytes, 102, 1102)
  mesh_peer.freshness(replayed) |> should.equal(mesh_peer.freshness(tripped))
  let assert Ok(recovered) = mesh_peer.receive_wire(replayed, "b", encode(SyncAck("b", [], "ok", 2)), 103, 1103)
  let assert [fresh] = mesh_peer.freshness(recovered).actors
  fresh.last_heartbeat_ms |> should.equal(103)
}
pub fn full_queue_tick_and_atomic_refusal_test() {
  let full = gossip_n(initial(), 256)
  mesh_peer.gossip(full, 5000) |> should.equal(Error(FrameQuota))
  let assert Ok(Tick(ticked, Error(FrameQuota))) = mesh_peer.tick(full, 101, 5000)
  mesh_peer.outbound(ticked) |> should.equal(mesh_peer.outbound(full))
  let #(cleared, actions, _) = mesh_peer.take_advisories(ticked)
  list.length(actions) |> should.equal(1)
  let assert Ok(Tick(again, _)) = mesh_peer.tick(cleared, 102, 5001)
  let #(_, repeated, _) = mesh_peer.take_advisories(again)
  repeated |> should.equal([])
  let delta = SyncDelta("b", delta_state.new_mesh_delta_state("b", 1), [], 1)
  mesh_peer.receive_wire(full, "b", encode(delta), 1, 1001) |> should.equal(Error(FrameQuota))
}
pub fn byte_quota_and_encode_refusal_test() {
  let peers = list.index_map(list.repeat(Nil, 16), fn(_, i) { Peer("b" <> int.to_string(i), "fqdn") })
  let state = configured(peers)
  let clock = list.index_map(list.repeat(Nil, 128), fn(_, i) { #(string.repeat("k", 500) <> int.to_string(i), 1) })
  let remote = delta_state.MeshDeltaState(..delta_state.new_mesh_delta_state("b0", 1), vector_clock: clock)
  let assert Ok(merged) = mesh_peer.receive_wire(state, "b0", encode(SyncDelta("b0", remote, [], 1)), 1, 1001)
  mesh_peer.gossip(merged, 1002) |> should.equal(Error(ByteQuota))
  mesh_peer.record_worker(state, string.repeat("x", 1025), 1002) |> result.is_error |> should.be_true
  mesh_peer.outbound(state) |> should.equal([])
}
pub fn clock_and_worker_roundtrip_test() {
  let state = initial()
  let assert Ok(worker) = mesh_peer.record_worker(state, "worker", 1001)
  let assert Ok(gossiped) = mesh_peer.gossip(worker, 1000)
  mesh_peer.engine_snapshot(gossiped).local_mesh_state.epoch_us |> should.equal(1001)
  mesh_peer.tick(gossiped, -1, 1000) |> should.equal(Error(InvalidClock))
  let assert Ok(Tick(advanced, _)) = mesh_peer.tick(gossiped, 10, 1002)
  mesh_peer.receive_wire(advanced, "b", encode(SyncAck("b", [], "ok", 1)), 9, 1003) |> should.equal(Error(InvalidClock))
}
pub fn utc_refusal_cannot_suppress_freshness_test() {
  let assert Ok(Tick(ticked, Error(InvalidClock))) = mesh_peer.tick(initial(), 100, -1)
  let assert [entry] = mesh_peer.freshness(ticked).actors
  entry.status |> should.equal(HeartbeatTripped(100))
  mesh_peer.outbound(ticked) |> should.equal([])
}
pub fn advisory_overflow_is_explicit_test() {
  let peers = list.index_map(list.repeat(Nil, 16), fn(_, i) { Peer("b" <> int.to_string(i), "fqdn") })
  let assert Ok(c) = mesh_peer.config("a", "fqdn", peers, 1, 1, 100)
  let assert Ok(initial) = mesh_peer.init(c, 0, 0, 1)
  let state = list.fold([1, 2, 3, 4, 5], initial, fn(s, time) { let assert Ok(Tick(next, _)) = mesh_peer.tick(s, time, time) next })
  let #(drained, actions, overflow) = mesh_peer.take_advisories(state)
  list.length(actions) |> should.equal(64)
  overflow |> should.equal(16)
  mesh_peer.advisory_overflow(drained) |> should.equal(0)
  list.length(mesh_peer.freshness(drained).actors) |> should.equal(16)
}

